1	// This component was a draft, unfinished.
2	// Feel free to either delete and recreate from the base from scratch, or continue and complete this, whichever easier.
3	
4	import React, { useRef, useState } from 'react';
5	import { useIntl } from 'react-intl';
6	import {
7	  useMultiStyleConfig,
8	  Box,
9	  Flex,
10	  IconButton,
11	  Badge,
12	  Button,
13	  Popover,
14	  PopoverHeader,
15	  PopoverTrigger,
16	  PopoverContent,
17	  PopoverBody,
18	  PopoverFooter,
19	  PopoverArrow,
20	  Stack,
21	  Text,
22	  Divider,
23	  useDisclosure,
24	  // useMediaQuery, // unused after layout change
25	} from '@salesforce/retail-react-app/app/components/shared/ui';
26	import { AuthHelpers, useAuthHelper, useCustomerType } from '@salesforce/commerce-sdk-react';
27	
28	import { useCurrentBasket } from '@salesforce/retail-react-app/app/hooks/use-current-basket';
29	
30	import Link from '@salesforce/retail-react-app/app/components/link';
31	import Search from '@salesforce/retail-react-app/app/components/search'; // TEMP: re-enabled for search API debugging
32	import withRegistration from '@salesforce/retail-react-app/app/components/with-registration';
33	import {
34	  AccountIcon,
35	  BasketIcon,
36	  BrandLogo,
37	  HamburgerIcon,
38	  ChevronDownIcon,
39	  HeartIcon,
40	  SearchIcon,
41	  SignoutIcon,
42	  StoreIcon,
43	  SparkleIcon,
44	} from '@salesforce/retail-react-app/app/components/icons';
45	
46	import { navLinks, messages } from '@salesforce/retail-react-app/app/pages/account/constant';
47	import useNavigation from '@salesforce/retail-react-app/app/hooks/use-navigation';
48	import { getConfig } from '@salesforce/pwa-kit-runtime/utils/ssr-config';
49	import LoadingSpinner from '@salesforce/retail-react-app/app/components/loading-spinner';
50	// import { HideOnDesktop, HideOnMobile } from '@salesforce/retail-react-app/app/components/responsive'; // replaced by inline display props
51	import { isHydrated, noop } from '@salesforce/retail-react-app/app/utils/utils';
52	import { STORE_LOCATOR_IS_ENABLED } from '@salesforce/retail-react-app/app/constants';
53	import { getCommerceAgentConfig } from '@salesforce/retail-react-app/app/utils/config-utils';
54	
55	const IconButtonWithRegistration = withRegistration(IconButton);
56	const ButtonWithRegistration = withRegistration(Button);
57	
58	type HeaderProps = {
59	  children?: React.ReactNode;
60	  onMenuClick?: () => void;
61	  onLogoClick?: () => void;
62	  onMyAccountClick?: () => void;
63	  onWishlistClick?: () => void;
64	  onMyCartClick?: () => void;
65	  onStoreLocatorClick?: () => void;
66	  onAgentClick?: () => void;
67	  searchInputRef?: React.Ref<HTMLInputElement>;
68	  [key: string]: unknown;
69	};
70	
71	type NavLink = {
72	  name: string;
73	  path: string;
74	  icon: React.ComponentType<{ boxSize: number }>;
75	};
76	
77	type OneClickCheckoutConfig = {
78	  enabled?: boolean;
79	};
80	
81	/**
82	 * Search bar for the header.
83	 *
84	 * The search bar is a simple input field with a search icon.
85	 * It can be used to search for products or navigate to a
86	 * specific page.
87	 *
88	 * @param props {object} the component props
89	 * @returns {Element} the search bar element
90	 */
91	// const SearchBar = (props: Record<string, unknown>) => {
92	//   const styles = useMultiStyleConfig('Header');
93	//   const intl = useIntl();
94	//   const placeholder = intl.formatMessage({
95	//     id: 'header.field.placeholder.search_for_products',
96	//     defaultMessage: 'Search for products...',
97	//   });
98	//   return (
99	//     <Box {...styles.searchContainer}>
100	//       <Search aria-label={placeholder} placeholder={placeholder} {...styles.search} {...props} />
101	//     </Box>
102	//   );
103	// };
104	
105	/**
106	 * The header is the main source for accessing
107	 * navigation, search, basket, and other
108	 * important information and actions. It persists
109	 * on the top of your application and will
110	 * respond to changes in device size.
111	 *
112	 * To customize the styles, update the themes
113	 * in theme/components/project/header.js
114	 * @param  props
115	 * @param   {func} props.onMenuClick click event handler for menu button
116	 * @param   {func} props.onLogoClick click event handler for menu button
117	 * @param   {object} props.searchInputRef reference of the search input
118	 * @param   {func} props.onMyAccountClick click event handler for my account button
119	 * @param   {func} props.onMyCartClick click event handler for my cart button
120	 * @param   {func} props.onAgentClick click event handler for agent button
121	 * @return  {React.ReactElement} - Header component
122	 */
123	const Header = ({
124	  children,
125	  onMenuClick = noop,
126	  onMyAccountClick = noop,
127	  onLogoClick = noop,
128	  onMyCartClick = noop,
129	  onWishlistClick = noop,
130	  onStoreLocatorClick = noop,
131	  onAgentClick = noop,
132	  ...props
133	}: HeaderProps) => {
134	  const intl = useIntl();
135	  const popoverTriggerRef = useRef<HTMLButtonElement>(null);
136	  const {
137	    derivedData: { totalItems },
138	    data: basket,
139	  } = useCurrentBasket();
140	  const { isRegistered } = useCustomerType();
141	  const logout = useAuthHelper(AuthHelpers.Logout);
142	  const navigate = useNavigation();
143	  const appConfig = getConfig().app;
144	  const storeLocatorEnabled = (appConfig?.storeLocatorEnabled as boolean | undefined) ?? STORE_LOCATOR_IS_ENABLED;
145	  const commerceAgentConfig = getCommerceAgentConfig();
146	  const showLaunchAgentButton = commerceAgentConfig?.enableAgentFromHeader === 'true';
147	  const {
148	    getButtonProps: getAccountMenuButtonProps,
149	    getDisclosureProps: getAccountMenuDisclosureProps,
150	    isOpen: isAccountMenuOpen,
151	    onClose: onAccountMenuClose,
152	    onOpen: onAccountMenuOpen,
153	  } = useDisclosure();
154	  // const [isDesktop] = useMediaQuery('(min-width: 992px)'); // unused after layout change: desktop account button always visible
155	
156	  const [showLoading, setShowLoading] = useState(false);
157	  // tracking if users enter the popover Content,
158	  // so we can decide whether to close the menu when users leave account icons
159	  const hasEnterPopoverContent = useRef<boolean>();
160	
161	  const styles = useMultiStyleConfig('Header');
162	  const { oneClickCheckout = {} } = appConfig as { oneClickCheckout?: OneClickCheckoutConfig };
163	  const isOneClickCheckoutEnabled = oneClickCheckout.enabled;
164	
165	  // Filter navigation links based on 1CC configuration
166	  const filteredNavLinks = isOneClickCheckoutEnabled
167	    ? (navLinks as NavLink[])
168	    : (navLinks as NavLink[]).filter((link) => link.name !== 'payments');
169	
170	  const onSignoutClick = async () => {
171	    setShowLoading(true);
172	    await logout.mutateAsync();
173	    navigate('/login');
174	    setShowLoading(false);
175	  };
176	
177	  const handleIconsMouseLeave = () => {
178	    // don't close the menu if users enter the popover content
179	    setTimeout(() => {
180	      if (!hasEnterPopoverContent.current) onAccountMenuClose();
181	    }, 100);
182	  };
183	
184	  const handleKeyDown = (event: React.KeyboardEvent) => {
185	    if (event.key === 'Tab' && event.shiftKey && isAccountMenuOpen) {
186	      // Prevent default behavior to keep focus on the popup trigger
187	      event.preventDefault();
188	      popoverTriggerRef.current?.focus();
189	    }
190	  };
191	
192	  return (
193	    <Box as="header" role="banner" {...styles.container} {...props}>
194	      <Box {...styles.content}>
195	        {showLoading && <LoadingSpinner wrapperStyles={{ height: '100vh' }} />}
196	
197	        {/* ── Row 1: top bar ─────────────────────────────────────────────── */}
198	        <Flex {...styles.topBar}>
199	          {/* Mobile only: hamburger */}
200	          <IconButton
201	            aria-label={intl.formatMessage({
202	              id: 'header.button.assistive_msg.menu',
203	              defaultMessage: 'Menu',
204	            })}
205	            title={intl.formatMessage({
206	              id: 'header.button.assistive_msg.menu.open_dialog',
207	              defaultMessage: 'Opens a dialog',
208	            })}
209	            icon={<HamburgerIcon />}
210	            variant="unstyled"
211	            display={{ base: 'flex', lg: 'none' }}
212	            {...styles.icons}
213	            onClick={onMenuClick}
214	          />
215	
216	          {/* Desktop left: nav categories (children) + search icon — no flex grow so space-between pushes Account/Saved/Bag to the right */}
217	          <Flex display={{ base: 'none', lg: 'flex' }} alignItems="center">
218	            <Box {...styles.bodyContainer}>{children}</Box>
219	            {/* TEMP: debug search input — remove once search overlay is implemented */}
220	            <Box ml={4} minW="240px">
221	              <Search
222	                placeholder={intl.formatMessage({
223	                  id: 'header.field.placeholder.search_for_products',
224	                  defaultMessage: 'Search for products...',
225	                })}
226	              />
227	            </Box>
228	          </Flex>
229	
230	          {/* Desktop right: Account | Saved | Bag as text */}
231	          <Flex display={{ base: 'none', lg: 'flex' }} alignItems="center" gap={5}>
232	            {showLaunchAgentButton && (
233	              <IconButton
234	                icon={<SparkleIcon />}
235	                aria-label={intl.formatMessage({
236	                  id: 'header.button.assistive_msg.ask_shopping_agent',
237	                  defaultMessage: 'Ask Shopping Agent',
238	                })}
239	                variant="unstyled"
240	                {...styles.icons}
241	                {...styles.agentIcon}
242	                onClick={onAgentClick}
243	              />
244	            )}
245	            <ButtonWithRegistration
246	              variant="unstyled"
247	              {...styles.desktopActionButton}
248	              onClick={onMyAccountClick}
249	              onMouseOver={onAccountMenuOpen}
250	            >
251	              Account
252	            </ButtonWithRegistration>
253	            {isRegistered && isHydrated() && (
254	              <Popover
255	                isLazy
256	                arrowSize={15}
257	                isOpen={isAccountMenuOpen}
258	                placement="bottom-end"
259	                onClose={onAccountMenuClose}
260	                onOpen={onAccountMenuOpen}
261	              >
262	                <PopoverTrigger>
263	                  <IconButton
264	                    aria-label={intl.formatMessage({
265	                      id: 'header.button.assistive_msg.my_account_menu',
266	                      defaultMessage: 'Open account menu',
267	                    })}
268	                    icon={<ChevronDownIcon />}
269	                    variant="unstyled"
270	                    {...styles.icons}
271	                    {...styles.arrowDown}
272	                    {...getAccountMenuButtonProps()}
273	                    onMouseOver={onAccountMenuOpen}
274	                    onMouseLeave={handleIconsMouseLeave}
275	                    ref={popoverTriggerRef}
276	                    onKeyDown={handleKeyDown}
277	                  />
278	                </PopoverTrigger>
279	
280	                <PopoverContent
281	                  {...styles.popoverContent}
282	                  onMouseLeave={() => {
283	                    hasEnterPopoverContent.current = false;
284	                    onAccountMenuClose();
285	                  }}
286	                  onMouseOver={() => {
287	                    hasEnterPopoverContent.current = true;
288	                  }}
289	                  {...getAccountMenuDisclosureProps()}
290	                >
291	                  <PopoverArrow />
292	                  <PopoverHeader>
293	                    <Text as="h2" fontSize="l" fontFamily="body" fontWeight="700">
294	                      {intl.formatMessage({
295	                        defaultMessage: 'My Account',
296	                        id: 'header.popover.title.my_account',
297	                      })}
298	                    </Text>
299	                  </PopoverHeader>
300	                  <PopoverBody>
301	                    <Box as="nav">
302	                      <Stack spacing={0} as="ul" data-testid="account-detail-nav">
303	                        {filteredNavLinks.map((link) => {
304	                          const LinkIcon = link.icon;
305	                          return (
306	                            <Box key={link.name} position="relative" as="li" listStyleType="none">
307	                              <Button
308	                                as={Link}
309	                                to={`/account${link.path}`}
310	                                useNavLink={true}
311	                                variant="menu-link"
312	                                leftIcon={<LinkIcon boxSize={5} />}
313	                                width="100%"
314	                              >
315	                                {intl.formatMessage(messages[link.name])}
316	                              </Button>
317	                            </Box>
318	                          );
319	                        })}
320	                      </Stack>
321	                    </Box>
322	                  </PopoverBody>
323	                  <PopoverFooter onClick={onSignoutClick} cursor="pointer">
324	                    <Divider colorScheme="gray" />
325	                    <Button variant="unstyled" {...styles.signout}>
326	                      <Flex>
327	                        <SignoutIcon aria-hidden={true} boxSize={5} {...styles.signoutIcon} />
328	                        <Text as="span" {...styles.signoutText}>
329	                          {intl.formatMessage({
330	                            defaultMessage: 'Log out',
331	                            id: 'header.popover.action.log_out',
332	                          })}
333	                        </Text>
334	                      </Flex>
335	                    </Button>
336	                  </PopoverFooter>
337	                </PopoverContent>
338	              </Popover>
339	            )}
340	            <ButtonWithRegistration variant="unstyled" {...styles.desktopActionButton} onClick={onWishlistClick}>
341	              Saved
342	            </ButtonWithRegistration>
343	            <Button variant="unstyled" {...styles.desktopActionButton} onClick={onMyCartClick}>
344	              Bag{basket && totalItems > 0 ? ` (${String(totalItems)})` : ''}
345	            </Button>
346	          </Flex>
347	
348	          {/* Mobile right: icon cluster */}
349	          <Flex display={{ base: 'flex', lg: 'none' }} alignItems="center" gap={2}>
350	            <IconButton
351	              aria-label={intl.formatMessage({
352	                id: 'header.button.assistive_msg.search',
353	                defaultMessage: 'Search',
354	              })}
355	              icon={<SearchIcon />}
356	              variant="unstyled"
357	              {...styles.icons}
358	            />
359	            {/* <IconButtonWithRegistration
360	              icon={<AccountIcon />}
361	              aria-label={intl.formatMessage({
362	                id: 'header.button.assistive_msg.my_account',
363	                defaultMessage: 'My Account',
364	              })}
365	              variant="unstyled"
366	              {...styles.icons}
367	              {...styles.accountIcon}
368	              onClick={onMyAccountClick}
369	            />
370	            <IconButtonWithRegistration
371	              aria-label={intl.formatMessage({
372	                defaultMessage: 'Wishlist',
373	                id: 'header.button.assistive_msg.wishlist',
374	              })}
375	              icon={<HeartIcon />}
376	              variant="unstyled"
377	              {...styles.icons}
378	              {...styles.wishlistIcon}
379	              onClick={onWishlistClick}
380	            /> */}
381	            {storeLocatorEnabled && (
382	              <IconButton
383	                aria-label={intl.formatMessage({
384	                  defaultMessage: 'Store Locator',
385	                  id: 'header.button.assistive_msg.store_locator',
386	                })}
387	                icon={<StoreIcon />}
388	                {...styles.icons}
389	                variant="unstyled"
390	                onClick={onStoreLocatorClick}
391	              />
392	            )}
393	            <IconButton
394	              aria-label={intl.formatMessage(
395	                {
396	                  id: 'header.button.assistive_msg.my_cart_with_num_items',
397	                  defaultMessage: 'My cart, number of items: {numItems}',
398	                },
399	                { numItems: totalItems },
400	              )}
401	              icon={
402	                <>
403	                  <BasketIcon />
404	                  {basket && totalItems > 0 && <Badge variant="notification">{totalItems}</Badge>}
405	                </>
406	              }
407	              variant="unstyled"
408	              {...styles.icons}
409	              onClick={onMyCartClick}
410	            />
411	          </Flex>
412	        </Flex>
413	
414	        {/* ── Row 2: logo only ────────────────────────────────────────────── */}
415	        <Flex {...styles.logoBar}>
416	          <Button
417	            aria-label={intl.formatMessage({
418	              id: 'header.button.assistive_msg.logo',
419	              defaultMessage: 'Logo',
420	            })}
421	            variant="unstyled"
422	            onClick={onLogoClick}
423	            {...styles.logoButton}
424	          >
425	            <BrandLogo {...styles.logo} />
426	          </Button>
427	        </Flex>
428	
429	        {/* Mobile-only search — commented out, pending searchPopover implementation */}
430	        {/* <HideOnDesktop display={{ base: 'block', lg: 'none' }}><SearchBar /></HideOnDesktop> */}
431	      </Box>
432	    </Box>
433	  );
434	};
435	
436	export default Header;
