// Feel free to either delete and recreate from the base from scratch, or continue and complete this, whichever easier.

import React, { useRef, useState } from 'react';
import { useIntl } from 'react-intl';
import {
  useMultiStyleConfig,
  Box,
  Flex,
  IconButton,
  Badge,
  Button,
  Popover,
  PopoverHeader,
  PopoverTrigger,
  PopoverContent,
  PopoverBody,
  PopoverFooter,
  PopoverArrow,
  Stack,
  Text,
  Divider,
  useDisclosure,
  // useMediaQuery, // unused after layout change
} from '@salesforce/retail-react-app/app/components/shared/ui';
import { AuthHelpers, useAuthHelper, useCustomerType } from '@salesforce/commerce-sdk-react';

import { useCurrentBasket } from '@salesforce/retail-react-app/app/hooks/use-current-basket';

import Link from '@salesforce/retail-react-app/app/components/link';
import Search from '@salesforce/retail-react-app/app/components/search'; // TEMP: re-enabled for search API debugging
import withRegistration from '@salesforce/retail-react-app/app/components/with-registration';
import {
  AccountIcon,
  BasketIcon,
  BrandLogo,
  HamburgerIcon,
  ChevronDownIcon,
  HeartIcon,
  SearchIcon,
  SignoutIcon,
  StoreIcon,
  SparkleIcon,
} from '@salesforce/retail-react-app/app/components/icons';

import { navLinks, messages } from '@salesforce/retail-react-app/app/pages/account/constant';
import useNavigation from '@salesforce/retail-react-app/app/hooks/use-navigation';
import { getConfig } from '@salesforce/pwa-kit-runtime/utils/ssr-config';
import LoadingSpinner from '@salesforce/retail-react-app/app/components/loading-spinner';
// import { HideOnDesktop, HideOnMobile } from '@salesforce/retail-react-app/app/components/responsive'; // replaced by inline display props
import { isHydrated, noop } from '@salesforce/retail-react-app/app/utils/utils';
import { STORE_LOCATOR_IS_ENABLED } from '@salesforce/retail-react-app/app/constants';
import { getCommerceAgentConfig } from '@salesforce/retail-react-app/app/utils/config-utils';

const IconButtonWithRegistration = withRegistration(IconButton);
const ButtonWithRegistration = withRegistration(Button);

type HeaderProps = {
  children?: React.ReactNode;
  onMenuClick?: () => void;
  onLogoClick?: () => void;
  onMyAccountClick?: () => void;
  onWishlistClick?: () => void;
  onMyCartClick?: () => void;
  onStoreLocatorClick?: () => void;
  onAgentClick?: () => void;
  searchInputRef?: React.Ref<HTMLInputElement>;
  [key: string]: unknown;
};

type NavLink = {
  name: string;
  path: string;
  icon: React.ComponentType<{ boxSize: number }>;
};

type OneClickCheckoutConfig = {
  enabled?: boolean;
};

/**
 * Search bar for the header.
 *
 * The search bar is a simple input field with a search icon.
 * It can be used to search for products or navigate to a
 * specific page.
 *
 * @param props {object} the component props
 * @returns {Element} the search bar element
 */
// const SearchBar = (props: Record<string, unknown>) => {
//   const styles = useMultiStyleConfig('Header');
//   const intl = useIntl();
//   const placeholder = intl.formatMessage({
//     id: 'header.field.placeholder.search_for_products',
//     defaultMessage: 'Search for products...',
//   });
//   return (
//     <Box {...styles.searchContainer}>
//       <Search aria-label={placeholder} placeholder={placeholder} {...styles.search} {...props} />
//     </Box>
//   );
// };

/**
 * The header is the main source for accessing
 * navigation, search, basket, and other
 * important information and actions. It persists
 * on the top of your application and will
 * respond to changes in device size.
 *
 * To customize the styles, update the themes
 * in theme/components/project/header.js
 * @param  props
 * @param   {func} props.onMenuClick click event handler for menu button
 * @param   {func} props.onLogoClick click event handler for menu button
 * @param   {object} props.searchInputRef reference of the search input
 * @param   {func} props.onMyAccountClick click event handler for my account button
 * @param   {func} props.onMyCartClick click event handler for my cart button
 * @param   {func} props.onAgentClick click event handler for agent button
 * @return  {React.ReactElement} - Header component
 */
const Header = ({
  children,
  onMenuClick = noop,
  onMyAccountClick = noop,
  onLogoClick = noop,
  onMyCartClick = noop,
  onWishlistClick = noop,
  onStoreLocatorClick = noop,
  onAgentClick = noop,
  ...props
}: HeaderProps) => {
  const intl = useIntl();
  const popoverTriggerRef = useRef<HTMLButtonElement>(null);
  const {
    derivedData: { totalItems },
    data: basket,
  } = useCurrentBasket();
  const { isRegistered } = useCustomerType();
  const logout = useAuthHelper(AuthHelpers.Logout);
  const navigate = useNavigation();
  const appConfig = getConfig().app;
  const storeLocatorEnabled = (appConfig?.storeLocatorEnabled as boolean | undefined) ?? STORE_LOCATOR_IS_ENABLED;
  const commerceAgentConfig = getCommerceAgentConfig();
  const showLaunchAgentButton = commerceAgentConfig?.enableAgentFromHeader === 'true';
  const {
    getButtonProps: getAccountMenuButtonProps,
    getDisclosureProps: getAccountMenuDisclosureProps,
    isOpen: isAccountMenuOpen,
    onClose: onAccountMenuClose,
    onOpen: onAccountMenuOpen,
  } = useDisclosure();
  // const [isDesktop] = useMediaQuery('(min-width: 992px)'); // unused after layout change: desktop account button always visible

  const [showLoading, setShowLoading] = useState(false);
  // tracking if users enter the popover Content,
  // so we can decide whether to close the menu when users leave account icons
  const hasEnterPopoverContent = useRef<boolean>();

  const styles = useMultiStyleConfig('Header');
  const { oneClickCheckout = {} } = appConfig as { oneClickCheckout?: OneClickCheckoutConfig };
  const isOneClickCheckoutEnabled = oneClickCheckout.enabled;

  // Filter navigation links based on 1CC configuration
  const filteredNavLinks = isOneClickCheckoutEnabled
    ? (navLinks as NavLink[])
    : (navLinks as NavLink[]).filter((link) => link.name !== 'payments');

  const onSignoutClick = async () => {
    setShowLoading(true);
    await logout.mutateAsync();
    navigate('/login');
    setShowLoading(false);
  };

  const handleIconsMouseLeave = () => {
    // don't close the menu if users enter the popover content
    setTimeout(() => {
      if (!hasEnterPopoverContent.current) onAccountMenuClose();
    }, 100);
  };

  const handleKeyDown = (event: React.KeyboardEvent) => {
    if (event.key === 'Tab' && event.shiftKey && isAccountMenuOpen) {
      // Prevent default behavior to keep focus on the popup trigger
      event.preventDefault();
      popoverTriggerRef.current?.focus();
    }
  };

  return (
    <Box as="header" role="banner" {...styles.container} {...props}>
      <Box {...styles.content}>
        {showLoading && <LoadingSpinner wrapperStyles={{ height: '100vh' }} />}

        {/* ── Row 1: top bar ─────────────────────────────────────────────── */}
        <Flex {...styles.topBar}>
          {/* Mobile only: hamburger */}
          <IconButton
            aria-label={intl.formatMessage({
              id: 'header.button.assistive_msg.menu',
              defaultMessage: 'Menu',
            })}
            title={intl.formatMessage({
              id: 'header.button.assistive_msg.menu.open_dialog',
              defaultMessage: 'Opens a dialog',
            })}
            icon={<HamburgerIcon />}
            variant="unstyled"
            display={{ base: 'flex', lg: 'none' }}
            {...styles.icons}
            onClick={onMenuClick}
          />

          {/* Desktop left: nav categories (children) + search icon — no flex grow so space-between pushes Account/Saved/Bag to the right */}
          <Flex display={{ base: 'none', lg: 'flex' }} alignItems="center">
            <Box {...styles.bodyContainer}>{children}</Box>
            {/* TEMP: debug search input — remove once search overlay is implemented */}
            <Box ml={4} minW="240px">
              <Search
                placeholder={intl.formatMessage({
                  id: 'header.field.placeholder.search_for_products',
                  defaultMessage: 'Search for products...',
                })}
              />
            </Box>
          </Flex>

          {/* Desktop right: Account | Saved | Bag as text */}
          <Flex display={{ base: 'none', lg: 'flex' }} alignItems="center" gap={5}>
            {showLaunchAgentButton && (
              <IconButton
                icon={<SparkleIcon />}
                aria-label={intl.formatMessage({
                  id: 'header.button.assistive_msg.ask_shopping_agent',
                  defaultMessage: 'Ask Shopping Agent',
                })}
                variant="unstyled"
                {...styles.icons}
                {...styles.agentIcon}
                onClick={onAgentClick}
              />
            )}
            <ButtonWithRegistration
              variant="unstyled"
              {...styles.desktopActionButton}
              onClick={onMyAccountClick}
              onMouseOver={onAccountMenuOpen}
            >
              Account
            </ButtonWithRegistration>
            {isRegistered && isHydrated() && (
              <Popover
                isLazy
                arrowSize={15}
                isOpen={isAccountMenuOpen}
                placement="bottom-end"
                onClose={onAccountMenuClose}
                onOpen={onAccountMenuOpen}
              >
                <PopoverTrigger>
                  <IconButton
                    aria-label={intl.formatMessage({
                      id: 'header.button.assistive_msg.my_account_menu',
                      defaultMessage: 'Open account menu',
                    })}
                    icon={<ChevronDownIcon />}
                    variant="unstyled"
                    {...styles.icons}
                    {...styles.arrowDown}
                    {...getAccountMenuButtonProps()}
                    onMouseOver={onAccountMenuOpen}
                    onMouseLeave={handleIconsMouseLeave}
                    ref={popoverTriggerRef}
                    onKeyDown={handleKeyDown}
                  />
                </PopoverTrigger>

                <PopoverContent
                  {...styles.popoverContent}
                  onMouseLeave={() => {
                    hasEnterPopoverContent.current = false;
                    onAccountMenuClose();
                  }}
                  onMouseOver={() => {
                    hasEnterPopoverContent.current = true;
                  }}
                  {...getAccountMenuDisclosureProps()}
                >
                  <PopoverArrow />
                  <PopoverHeader>
                    <Text as="h2" fontSize="l" fontFamily="body" fontWeight="700">
                      {intl.formatMessage({
                        defaultMessage: 'My Account',
                        id: 'header.popover.title.my_account',
                      })}
                    </Text>
                  </PopoverHeader>
                  <PopoverBody>
                    <Box as="nav">
                      <Stack spacing={0} as="ul" data-testid="account-detail-nav">
                        {filteredNavLinks.map((link) => {
                          const LinkIcon = link.icon;
                          return (
                            <Box key={link.name} position="relative" as="li" listStyleType="none">
                              <Button
                                as={Link}
                                to={`/account${link.path}`}
                                useNavLink={true}
                                variant="menu-link"
                                leftIcon={<LinkIcon boxSize={5} />}
                                width="100%"
                              >
                                {intl.formatMessage(messages[link.name])}
                              </Button>
                            </Box>
                          );
                        })}
                      </Stack>
                    </Box>
                  </PopoverBody>
                  <PopoverFooter onClick={onSignoutClick} cursor="pointer">
                    <Divider colorScheme="gray" />
                    <Button variant="unstyled" {...styles.signout}>
                      <Flex>
                        <SignoutIcon aria-hidden={true} boxSize={5} {...styles.signoutIcon} />
                        <Text as="span" {...styles.signoutText}>
                          {intl.formatMessage({
                            defaultMessage: 'Log out',
                            id: 'header.popover.action.log_out',
                          })}
                        </Text>
                      </Flex>
                    </Button>
                  </PopoverFooter>
                </PopoverContent>
              </Popover>
            )}
            <ButtonWithRegistration variant="unstyled" {...styles.desktopActionButton} onClick={onWishlistClick}>
              Saved
            </ButtonWithRegistration>
            <Button variant="unstyled" {...styles.desktopActionButton} onClick={onMyCartClick}>
              Bag{basket && totalItems > 0 ? ` (${String(totalItems)})` : ''}
            </Button>
          </Flex>

          {/* Mobile right: icon cluster */}
          <Flex display={{ base: 'flex', lg: 'none' }} alignItems="center" gap={2}>
            <IconButton
              aria-label={intl.formatMessage({
                id: 'header.button.assistive_msg.search',
                defaultMessage: 'Search',
              })}
              icon={<SearchIcon />}
              variant="unstyled"
              {...styles.icons}
            />
            {/* <IconButtonWithRegistration
              icon={<AccountIcon />}
              aria-label={intl.formatMessage({
                id: 'header.button.assistive_msg.my_account',
                defaultMessage: 'My Account',
              })}
              variant="unstyled"
              {...styles.icons}
              {...styles.accountIcon}
              onClick={onMyAccountClick}
            />
            <IconButtonWithRegistration
              aria-label={intl.formatMessage({
                defaultMessage: 'Wishlist',
                id: 'header.button.assistive_msg.wishlist',
              })}
              icon={<HeartIcon />}
              variant="unstyled"
              {...styles.icons}
              {...styles.wishlistIcon}
              onClick={onWishlistClick}
            /> */}
            {storeLocatorEnabled && (
              <IconButton
                aria-label={intl.formatMessage({
                  defaultMessage: 'Store Locator',
                  id: 'header.button.assistive_msg.store_locator',
                })}
                icon={<StoreIcon />}
                {...styles.icons}
                variant="unstyled"
                onClick={onStoreLocatorClick}
              />
            )}
            <IconButton
              aria-label={intl.formatMessage(
                {
                  id: 'header.button.assistive_msg.my_cart_with_num_items',
                  defaultMessage: 'My cart, number of items: {numItems}',
                },
                { numItems: totalItems },
              )}
              icon={
                <>
                  <BasketIcon />
                  {basket && totalItems > 0 && <Badge variant="notification">{totalItems}</Badge>}
                </>
              }
              variant="unstyled"
              {...styles.icons}
              onClick={onMyCartClick}
            />
          </Flex>
        </Flex>

        {/* ── Row 2: logo only ────────────────────────────────────────────── */}
        <Flex {...styles.logoBar}>
          <Button
            aria-label={intl.formatMessage({
              id: 'header.button.assistive_msg.logo',
              defaultMessage: 'Logo',
            })}
            variant="unstyled"
            onClick={onLogoClick}
            {...styles.logoButton}
          >
            <BrandLogo {...styles.logo} />
          </Button>
        </Flex>

        {/* Mobile-only search — commented out, pending searchPopover implementation */}
        {/* <HideOnDesktop display={{ base: 'block', lg: 'none' }}><SearchBar /></HideOnDesktop> */}
      </Box>
    </Box>
  );
};

export default Header;

